for line in rows.strip().splitlines():
 g,name,terms,src,core,explain,example,confusion,ask,answer=line.split('|')
 tid='e413-'+re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
 refs=[{'id':'E413','pages':[int(n) for n in src.split(',')]}] if src[0].isdigit() else [{'id':'e413-'+src}]
 q1={'id':tid+'-core','prompt':'What is '+name.lower()+'?' if ' and ' not in name and not name.endswith('s') else 'Explain '+name.lower()+' briefly.','type':'definition','difficulty':'foundation','essential':name in essential_titles,'shortAnswer':core,'answer':core+' '+explain.split('. ')[0]+'.','keyPoints':[core],'followUps':[tid+'-apply']}
 q2={'id':tid+'-apply','prompt':ask,'type':'criticism' if name in challenges else 'application','difficulty':'challenge' if name in challenges else 'applied','essential':False,'shortAnswer':answer.split('. ')[0]+('.' if '. ' in answer else ''),'answer':answer,'keyPoints':re.split(r'(?<=[.!?])\s+(?=[A-Z])',answer),'followUps':[]}
 topics.append({'id':tid,'groupId':'e413-'+g,'title':name,'aliases':['research methodology'] if g=='foundations' else [],'core':core,'explanation':explain,'example':example,'confusion':confusion,'syllabusTerms':terms.split(';'),'sources':refs,'related':[],'questions':[q1,q2]})
course={'id':'E413','title':'Research Methods in Applied Linguistics and ELT','shortTitle':'Research Methods','overview':'Research connects a worthwhile question with suitable evidence and a defensible answer. Move from problem and literature to design, participants and instruments, then analysis, interpretation and responsible reporting. Every choice should fit the question.','journey':['Find the uncertainty: problem, literature, gap and research questions.','Choose evidence that can answer it: design, sample, instruments and ethics.','Turn evidence into a justified answer: analyse, interpret and acknowledge limitations.','Explain the contribution: report, cite and recommend within the evidence.'],'sources':sources,'groups':[{'id':'e413-'+g,'title':t,'syllabus':s} for g,t,s in groups],'topics':topics}
(root/'content/E413.json').write_text(json.dumps(course,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'E413: {len(topics)} topics, {len(topics)*2} questions, {sum(q["essential"] for t in topics for q in t["questions"])} essentials')
